/* Flipbook service worker. Generated by tools/build_sw.py — edit tools/sw.template.js. */
const VERSION = '__VERSION__';
const SHELL_CACHE = 'flipbook-' + VERSION;
const SHELL = __SHELL__;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(SHELL_CACHE);
    for (let i = 0; i < SHELL.length; i += 24) {
      const chunk = SHELL.slice(i, i + 24);
      await cache.addAll(chunk.map((url) => new Request(url, { cache: 'reload' })));
    }
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((key) => key.startsWith('flipbook-') && key !== SHELL_CACHE).map((key) => caches.delete(key)));
    await self.clients.claim();
  })());
});

self.addEventListener('message', (event) => {
  if (event.data === 'skipWaiting') self.skipWaiting();
});

const scopePath = new URL(self.registration.scope).pathname;

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== location.origin || !url.pathname.startsWith(scopePath)) return;
  const rel = url.pathname.slice(scopePath.length);
  if (rel === 'sw.js') return;

  if (req.mode === 'navigate' || rel === '' || rel === 'index.html') {
    event.respondWith((async () => {
      const cache = await caches.open(SHELL_CACHE);
      return (await cache.match('index.html'))
        || (await cache.match('./'))
        || (await caches.match(req, { ignoreSearch: true }))
        || fetch(req);
    })());
    return;
  }

  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      const res = await fetch(req);
      if (res && res.ok && res.type === 'basic') {
        const cache = await caches.open(SHELL_CACHE);
        cache.put(req, res.clone());
      }
      return res;
    } catch (err) {
      if (req.destination === 'document') {
        const cache = await caches.open(SHELL_CACHE);
        return (await cache.match('index.html')) || (await cache.match('./')) || Response.error();
      }
      return Response.error();
    }
  })());
});
